const s = $input.first()?.json || {};
const required = ['config_revision', 'chat_model', 'embedding_model', 'embedding_profile_id', 'embedding_dimension', 'ai_timeout_max'];
const missing = required.filter((key) => s[key] === null || s[key] === undefined || s[key] === '' || s[key] === 'UNINITIALIZED');
if (missing.length) throw new Error(`rag_settings_incomplete:${missing.join(',')}`);
if (!Number.isInteger(Number(s.embedding_dimension)) || Number(s.embedding_dimension) <= 0) throw new Error(`embedding_dimension_invalid:${s.embedding_dimension}`);
if (!Number.isInteger(Number(s.ai_timeout_max)) || Number(s.ai_timeout_max) <= 0) throw new Error(`ai_timeout_invalid:${s.ai_timeout_max}`);
return [{ json: s }];

const files = $input.all();
const manifest = [];
for (const f of files) {
  const name = f.binary?.data?.fileName || f.json.fileName || f.json.filename || '';
  const content = f.binary?.data?.data ? Buffer.from(f.binary.data.data, 'base64').toString('utf8') : '';
  if (!/^\d{2}_.+\.md$/.test(name)) throw new Error('bad_corpus_filename');
  if (!content.trim()) throw new Error('empty_corpus_file');
  if (name.includes('..') || name.includes('/') || name.includes('\\')) throw new Error('path_traversal');
  manifest.push({ name, content, hash: require('crypto').createHash('sha256').update(content).digest('hex') });
}
if (!manifest.length) throw new Error('empty_corpus');
manifest.sort((a, b) => a.name.localeCompare(b.name));
return manifest.map((m) => ({ json: m }));

const CHUNK_SIZE = 800;
const chunks = [];
for (const item of $input.all()) {
  const { name, content, hash } = item.json;
  const paragraphs = content.split(/\n\s*\n/);
  let buffer = '';
  let index = 0;
  for (const paragraph of paragraphs) {
    if ((buffer + paragraph).length > CHUNK_SIZE && buffer) {
      chunks.push({ source_name: name, source_hash: hash, chunk_index: index++, content: buffer });
      buffer = paragraph;
    } else {
      buffer = buffer ? `${buffer}\n\n${paragraph}` : paragraph;
    }
  }
  if (buffer) chunks.push({ source_name: name, source_hash: hash, chunk_index: index++, content: buffer });
}
if (!chunks.length) throw new Error('empty_chunk_set');
return chunks.map((chunk) => ({ json: chunk }));

const settings = $('Load RAG Settings').first().json;
const chunks = $input.all();
const input = chunks.map((item) => item.json.content);
if (!input.length) throw new Error('empty_embedding_batch');
const requestBody = JSON.stringify({ model: settings.embedding_model, input });
return [{ json: { request_body: requestBody, chunk_count: input.length } }];

const settings = $('Load RAG Settings').first().json;
const chunks = $('Chunk Documents').all();
const response = $input.first()?.json || {};
const vectors = response.data || [];
const dimension = Number(settings.embedding_dimension);
if (vectors.length !== chunks.length) throw new Error('embedding_count_mismatch');
const pairs = chunks.map((chunk, index) => ({ source_name: chunk.json.source_name, source_hash: chunk.json.source_hash, chunk_index: chunk.json.chunk_index, content: chunk.json.content, embedding: vectors[index].embedding, embedding_profile_id: settings.embedding_profile_id }));
for (const pair of pairs) {
  if (!Array.isArray(pair.embedding) || pair.embedding.length !== dimension) throw new Error('embedding_dimension_mismatch');
}
return pairs.map((pair) => ({ json: pair }));

const manifest = $('Build Manifest & Validate').all().map((item) => ({ name: item.json.name, hash: item.json.hash })).sort((a, b) => a.name.localeCompare(b.name));
const settings = $('Load RAG Settings').first().json;
const chunks = $input.all().map((item) => item.json);
const manifestHash = require('crypto').createHash('sha256').update(JSON.stringify(manifest)).digest('hex');
return [{ json: { corpus_version: `sha256:${manifestHash}`, document_count: manifest.length, chunk_count: chunks.length, embedding_profile_id: settings.embedding_profile_id, config_revision: settings.config_revision, chunks } }];

const batch = $('Prepare Ingest Batch').first().json;
if (!batch?.corpus_version || !batch?.embedding_profile_id || !Array.isArray(batch?.chunks)) throw new Error('ingest_batch_unavailable');
return [{ json: batch }];

const batch = $('Prepare Ingest Batch').first().json;
const evidence = $input.first()?.json || {};
const expectedChunks = Number(batch.chunk_count);
const expectedDocuments = Number(batch.document_count);
const persistedChunks = Number(evidence.persisted_chunk_count);
const persistedDocuments = Number(evidence.persisted_document_count);
const validStatus = evidence.status === 'staging' || evidence.status === 'active';
if (!batch.corpus_version || !batch.embedding_profile_id || evidence.corpus_version !== batch.corpus_version || evidence.embedding_profile_id !== batch.embedding_profile_id || !validStatus || persistedChunks !== expectedChunks || persistedDocuments !== expectedDocuments) {
  throw new Error(`candidate_validation_failed:status=${evidence.status || 'missing'},chunks=${persistedChunks}/${expectedChunks},documents=${persistedDocuments}/${expectedDocuments}`);
}
const { chunks, ...candidate } = batch;
return [{ json: { ...candidate, persisted_chunk_count: persistedChunks, persisted_document_count: persistedDocuments, valid: true } }];

let batch = {};
try { batch = $('Prepare Ingest Batch').first().json || {}; } catch (_) {}
const inputErrors = $input.all().map((item) => item.json?.error ?? item.error ?? item.json?.message).map((error) => typeof error === 'string' ? error : error?.message).filter(Boolean);
const failureReason = String(inputErrors[0] || 'workflow_failure').slice(0, 500);
return [{ json: { status: 'failed', corpus_version: batch.corpus_version || null, error_category: failureReason, has_candidate: Boolean(batch.corpus_version) } }];
